/*
 * SNOOZE A "GONE QUIET" ITEM FOR A WEEK (DBU-08). role:staff is checked by nodegx.security.json.
 * Only an open flag. `nudged` records that the coach wrote to the learner (the inbox's nudge), which
 * also snoozes it: the list empties, and the item is back in a week if she is still quiet.
 * morningRound closes the flag earlier if she becomes active. Rings a staff-only bell, so every open
 * inbox and the Inbox tab re-read.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const SNOOZE_DAYS = 7;
    const id = String(Inputs.flagId || '');
    const found = id ? await Noodl.Records.query('QuietFlag', { objectId: { equalTo: id } }, { limit: 2, plain: true }) : [];
    const flag = found[0];
    if (!flag || flag.closedAt) return refuse('This item has already gone from the inbox. Reload the page.');
    const now = new Date();
    const until = new Date(now.getTime() + SNOOZE_DAYS * 86400000).toISOString();
    const change = { snoozedUntil: until };
    if (Inputs.nudged === true) change.nudgedAt = now.toISOString();
    await Noodl.Records.save(flag.objectId, change, { className: 'QuietFlag' });
    await Noodl.Records.create('Doorbell', { learner: flag.learner, topic: 'inbox' }, { acl: { 'role:staff': { read: true } } });
    Outputs.snoozedUntil = until;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:snoozeQuiet]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
